/**
 * emit to subscription queries of type FindAppointment,
 * but only if the id matches
 *
 * @param		entity	Appointment
 */
	protected void emitFindAppointment( Appointment entity ) {
		LOGGER.info("handling emitFindAppointment" );
		
	    queryUpdateEmitter.emit(FindAppointmentQuery.class,
	                            query -> query.getFilter().getAppointmentId().equals(entity.getAppointmentId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllAppointment
	 * 
	 * @param		entity	Appointment
	 */
	protected void emitFindAllAppointment( Appointment entity ) {
		LOGGER.info("handling emitFindAllAppointment" );
		
	    queryUpdateEmitter.emit(FindAllAppointmentQuery.class,
	                            query -> true,
	                            entity);
	}

